tools.schema:
{
  "type": "object",
  "properties": {
    "image_url": {
      "type": "string",
      "description": "图片链接"
    },
    "target_language": {
      "type": "string",
      "description": "目标语言"
    },
    "platform": {
      "type": "string",
      "description": "目标平台"
    }
  },
  "required": [
    "image_url",
    "target_language"
  ]
}

{
  "type": "object",
  "properties": {
    "design_image": {
      "type": "string",
      "description": "图案文件链接"
    },
    "product_type": {
      "type": "string",
      "description": "载体，如 T恤、马克杯"
    },
    "print_area": {
      "type": "string",
      "description": "印花位置"
    },
    "color": {
      "type": "string",
      "description": "产品底色，可多个"
    }
  },
  "required": [
    "design_image",
    "product_type"
  ]
}

{
  "type": "object",
  "properties": {
    "text": {
      "type": "string",
      "description": "图案描述 / 文字"
    },
    "image_url": {
      "type": "string",
      "description": "图片链接"
    }
  },
  "required": [
    "text"
  ]
}

{
  "type": "object",
  "properties": {
    "query": {
      "type": "string",
      "description": "检索问题"
    },
    "kb_id": {
      "type": "string",
      "description": "限定知识库，不填检索全部"
    },
    "platform": {
      "type": "string"
    },
    "site": {
      "type": "string"
    },
    "language": {
      "type": "string"
    },
    "category": {
      "type": "string"
    },
    "top_k": {
      "type": "integer",
      "description": "返回条数，默认 5"
    }
  },
  "required": [
    "query"
  ]
}

{
  "type": "object",
  "properties": {
    "marketplace": {
      "type": "string",
      "description": "站点，如 US"
    },
    "asins": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "ASIN 列表"
    },
    "includeFields": {
      "type": "string",
      "description": "返回字段，选填"
    }
  },
  "required": [
    "marketplace",
    "asins"
  ]
}
